// Quelle für den Normalisieren-Knoten in Workflow 01 (wird als jsCode eingebettet).
// Vereinheitlicht die drei Datenformate und holt heraus, was die Prüfdienste brauchen.

// Einfaches Format -> from / subject / snippet
// IMAP-Trigger  -> from.value[].address / subject / text | textPlain, headers/headerLines
// IMAP-Node     -> envelope.from[].address / envelope.subject / textContent, headers
const j = $json;
const e = j.envelope || {};
const h = j.headers || {};

const von = (e.from && e.from[0] && e.from[0].address)
  || (j.from && j.from.value && j.from.value[0] && j.from.value[0].address)
  || (j.from && j.from.text)
  || j.From
  || (typeof j.from === 'string' ? j.from : '')
  || '';

const betreff = e.subject || j.subject || j.Subject || '(kein Betreff)';

let volltext = j.textContent || j.textPlain || j.text || j.snippet || j.textHtml || '';
if (typeof volltext !== 'string') volltext = JSON.stringify(volltext);

// ── Absender-IP aus den Received-Kopfzeilen ────────────────────────────────
// Die oberste Received-Zeile hat der eigene Mailserver geschrieben und enthält
// die IP, von der die Mail tatsächlich kam — nur die ist vertrauenswürdig.
function absenderIp() {
  let received = h.received || h.Received;
  if (!received && Array.isArray(j.headerLines)) {
    received = j.headerLines
      .filter((z) => String(z.key || '').toLowerCase() === 'received')
      .map((z) => z.line);
  }
  if (!received) return null;
  const zeilen = Array.isArray(received) ? received : [received];
  // Adressen aus privaten und reservierten Netzen sagen nichts über den Absender
  const intern = /^(10\.|127\.|169\.254\.|192\.168\.|172\.(1[6-9]|2\d|3[01])\.|0\.)/;
  for (const zeile of zeilen) {
    const gefunden = String(zeile).match(/\b\d{1,3}(?:\.\d{1,3}){3}\b/g) || [];
    const treffer = gefunden.find((ip) => !intern.test(ip));
    if (treffer) return treffer;
  }
  return null;
}

// ── Links im Text (für die spätere Safe-Browsing-Prüfung) ──────────────────
const links = [...new Set((volltext.match(/https?:\/\/[^\s<>"')\]]+/gi) || []))].slice(0, 20);

// ── Abmelde-Link (für die Newsletter-Verwaltung) ───────────────────────────
const listUnsubscribe = h['list-unsubscribe']
  || (h.list && h.list.unsubscribe && (h.list.unsubscribe.url || h.list.unsubscribe.id))
  || null;

const text = volltext.replace(/<[^>]+>/g, ' ').replace(/\s+/g, ' ').trim().slice(0, 1500);

const promptText = `Du bist ein E-Mail-Klassifizierer. Analysiere die folgende E-Mail und antworte NUR mit einem JSON-Objekt in exakt diesem Format:
{"kategorie": "spam|rechnung|bestellung|newsletter|persoenlich|sonstiges", "spam_score": 0.0, "kurzfassung": "Ein Satz Zusammenfassung auf Deutsch"}

Regeln:
- spam_score: 0.0 (sicher kein Spam) bis 1.0 (sicher Spam). Phishing, Betrugsversuche, unserioese Werbung = hoher Score.
- kategorie "rechnung": Rechnungen, Zahlungsaufforderungen, Kontoauszuege, Vertraege.
- kategorie "bestellung": Bestell-/Versandbestaetigungen, Lieferstatus.
- kategorie "newsletter": Newsletter und Marketing serioeser Absender.
- kategorie "persoenlich": Mails von echten Menschen (privat oder geschaeftlich).
- Alles andere: "sonstiges".

E-Mail:
Von: ${von}
Betreff: ${betreff}
Text: ${text}`;

return {
  json: {
    konto: j.konto,
    uid: j.uid ?? null,
    id: j.id ?? null,
    von,
    betreff,
    ip: absenderIp(),
    links,
    listUnsubscribe: typeof listUnsubscribe === 'string' ? listUnsubscribe : null,
    promptText,
  },
};

// Gemini-Antwort auswerten und den Zielordner bestimmen.
// Die Panel-Prüfung (Listen, DNSBL) fließt dabei mit ein.
const mail = $('Prüfung auswerten').item.json;

let raw = '';
try { raw = $json.candidates[0].content.parts[0].text; } catch (e) { /* leer lassen */ }
raw = String(raw).replace(/```json|```/g, '').trim();

let k = { kategorie: 'sonstiges', spam_score: 0, kurzfassung: '' };
try { k = { ...k, ...JSON.parse(raw) }; } catch (e) { /* Fallback: sonstiges */ }


// DNSBL-Treffer erhöhen die Bewertung der KI
const schwelle = Number(mail.spam_schwellwert) || 0.8;
const score = Math.min(1, (Number(k.spam_score) || 0) + (Number(mail.score_aufschlag) || 0));

let zielordner = null;
if (score > schwelle && !mail.nie_quarantaene) zielordner = mail.folder_spam || 'Quarantaene';
else if (k.kategorie === 'rechnung') zielordner = mail.folder_invoices || 'Rechnungen';
else if (k.kategorie === 'bestellung') zielordner = mail.folder_orders || 'Bestellungen';
else if (k.kategorie === 'newsletter') zielordner = mail.folder_newsletter || 'Newsletter';

return {
  json: {
    ...mail,
    kategorie: k.kategorie,
    spam_score: score,
    kurzfassung: k.kurzfassung,
    zielordner,
  },
};

// Ergebnis der Panel-Prüfung mit der Mail zusammenführen.
// Whitelist beendet die Prüfung sofort, Blacklist geht ohne KI in die Quarantäne.
const mail = $('Normalisieren').item.json;
const p = $json || {};

const entscheidung = p.entscheidung || 'weiter';
const gruende = Array.isArray(p.gruende) ? p.gruende : [];

return {
  json: {
    ...mail,
    entscheidung,
    score_aufschlag: Number(p.score_aufschlag) || 0,
    spam_schwellwert: Number(p.spam_schwellwert) || 0.8,
    gruende,
    dnsbl_treffer: p.dnsbl_treffer || [],
    // Blacklist braucht keine KI-Abfrage mehr
    direkt_quarantaene: entscheidung === 'quarantaene',
    // Whitelist übersteuert später auch die KI-Bewertung
    nie_quarantaene: entscheidung === 'freigeben',
  },
};

// Blacklist-Treffer: ohne KI direkt in die Quarantäne
const m = $json;
return { json: { ...m, kategorie: 'spam', spam_score: 1, kurzfassung: m.gruende.join('; ') || 'Absender steht auf der Blacklist', zielordner: 'Quarantaene' } };

// Die Sortier-Regel hat gegriffen — Zielordner übernehmen, ohne KI-Abfrage
const m = $json;
return {
  json: {
    ...m,
    zielordner: m.sort_ordner,
    kategorie: 'sortierung',
    spam_score: 0,
    kurzfassung: 'Automatisch nach eigener Regel einsortiert',
  },
};

// Antwort des Panels mit der Mail zusammenführen.
// Der HTTP-Knoten davor ersetzt das Item durch seine Antwort — ohne diesen
// Schritt hätten alle folgenden Knoten keine Maildaten mehr.
const mail = $('Normalisieren').item.json;
const s = $json || {};
return {
  json: {
    ...mail,
    sort_aktion: s.aktion || 'inbox',
    sort_ordner: s.ordner || null,
  },
};
